const email = $json;
const subject = String(email.subject ?? email.Subject ?? email.headers?.subject ?? '');
const titleMatch = subject.match(/\b(Sprint Planning|Sprint Estimating)\b/i);
const html = [email.textHtml, email.textAsHtml, email.html, email.textPlain, email.text, email.snippet].filter(Boolean).join('\n');
const docMatch = html.match(/(?:https?:\/\/)?docs\.google\.com\/document\/d\/([a-zA-Z0-9_-]+)/i);
const docId = docMatch?.[1] ?? email.docId ?? null;
const receivedAt = email.internalDate ?? email.date ?? new Date().toISOString();
return [{ json: {
  subject,
  title: titleMatch?.[1] ?? null,
  meetingDate: receivedAt,
  docId,
  docUrl: docId ? `https://docs.google.com/document/d/${docId}/edit` : null,
  emailId: email.id ?? email.messageId ?? null,
  sourceEmail: email,
} }];

const identity = $('Extract Meeting Identity').item.json;
const staticData = $getWorkflowStaticData('global');
staticData.meetingDocs = staticData.meetingDocs || {};
const prior = identity.docId ? staticData.meetingDocs[identity.docId] : null;
if (prior) {
  return [{ json: { ...identity, route: 'duplicate', calendarVerified: false, reason: `Doc ID already processed with status ${prior.status}.` } }];
}
if (!identity.title || !identity.docId) {
  return [{ json: { ...identity, route: 'ignore', calendarVerified: false, reason: 'Gemini subject is not Sprint Planning/Estimating or the Google Doc ID is missing.' } }];
}
staticData.meetingDocs[identity.docId] = { status: 'processing', startedAt: Date.now(), title: identity.title };
return [{ json: { ...identity, route: 'accept', calendarVerified: false, meetingIdentityVerified: true, reason: 'Accepted from filtered Gemini meeting identity and Doc ID.' } }];

const event = $json.body ?? $json;
const action = event.action ?? event.common?.invokedFunction ?? {};
const parameters = Object.fromEntries((action.parameters ?? []).map((p) => [p.key, p.value]));
const method = event.decision ?? action.actionMethodName ?? parameters.action ?? null;
const reviewId = event.reviewId ?? parameters.reviewId;
const selected = Array.isArray(event.selectedItemIds)
  ? event.selectedItemIds
  : (event.common?.formInputs?.itemIds?.stringInputs?.value ?? event.action?.formInputs?.itemIds?.stringInputs?.value ?? []);
const comment = event.comment
  ?? event.common?.formInputs?.reviewComment?.stringInputs?.value?.[0]
  ?? event.action?.formInputs?.reviewComment?.stringInputs?.value?.[0]
  ?? '';
const staticData = $getWorkflowStaticData('global');
const review = Object.values(staticData.meetingDocs || {}).find((entry) => entry.reviewId === reviewId);
if (!review) throw new Error('Review not found or expired.');
if (['discard_review', 'reject_selected', 'request_changes'].includes(method)) {
  review.status = method === 'discard_review' ? 'discarded' : method === 'reject_selected' ? 'rejected' : 'changes_requested';
  review.reviewComment = comment;
  return [{ json: { route: 'review_update', response: { text: `Review ${review.status.replace('_', ' ')}. No issues were created.` }, reviewId } }];
}
if (method !== 'approve_selected') {
  return [{ json: { route: 'review_update', response: { text: 'Unsupported review action. No issues were created.' }, reviewId } }];
}
const selectedSet = new Set(selected);
const candidates = review.items.filter((item) => selectedSet.has(item.itemId) && ['repo-work', 'design-work'].includes(item.classification));
if (!candidates.length) {
  return [{ json: { route: 'review_update', response: { text: 'No eligible repo-work or design-work items were selected. No issues were created.' }, reviewId } }];
}
review.status = 'approved';
review.reviewComment = comment;
return candidates.map((item) => ({ json: { route: 'create', reviewId, docUrl: review.docUrl, reviewComment: comment, item } }));
